DO $$ DECLARE definition text; BEGIN SELECT pg_get_functiondef('public.tms_records_commit(jsonb,text)'::regprocedure) INTO definition; definition:=replace(definition, 'ARRAY[''costs'',''cteValor'',''divergenciaPercent'',''conferencia'',''valorNF'']', 'ARRAY[''costs'',''cteValor'',''divergenciaPercent'',''conferencia'',''valorNF'',''valorFrete'',''xmlOriginal'']'); definition:=replace(definition, '''valorNF'',current_row.data->''valorNF''', '''valorNF'',current_row.data->''valorNF'',''valorFrete'',current_row.data->''valorFrete'',''xmlOriginal'',current_row.data->''xmlOriginal'''); EXECUTE definition; END $$;
CREATE OR REPLACE FUNCTION public.tms_ledger_validate() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE movement jsonb; total numeric:=0; legacy numeric:=0; amount numeric; previous jsonb; original jsonb; seen text[]:='{}'; BEGIN IF NEW.collection NOT IN ('invoices','expenses') THEN RETURN NEW; END IF; IF TG_OP='UPDATE' AND NEW.data->'movements' IS NOT DISTINCT FROM OLD.data->'movements' THEN RETURN NEW; END IF; IF TG_OP='UPDATE' THEN FOR previous IN SELECT value FROM jsonb_array_elements(coalesce(OLD.data->'movements','[]'::jsonb)) LOOP IF NOT coalesce(NEW.data->'movements','[]'::jsonb) @> jsonb_build_array(previous) THEN RAISE EXCEPTION 'Histórico de baixas não pode ser apagado ou alterado'; END IF; END LOOP; END IF; legacy:=coalesce((NEW.data->>CASE WHEN NEW.collection='invoices' THEN 'valorRecebido' ELSE 'valorPago' END)::numeric,0); total:=legacy; FOR movement IN SELECT value FROM jsonb_array_elements(coalesce(NEW.data->'movements','[]'::jsonb)) LOOP amount:=(movement->>'value')::numeric; IF amount<=0 OR amount IS NULL OR movement->>'id'=ANY(seen) OR coalesce(movement->>'author','')='' OR coalesce(movement->>'reason','')='' OR movement->>'date' !~ '^\d{4}-\d{2}-\d{2}$' THEN RAISE EXCEPTION 'Movimentação inválida'; END IF; PERFORM (movement->>'date')::date; seen:=array_append(seen,movement->>'id'); IF movement->>'type'='baixa' THEN total:=total+amount; ELSIF movement->>'type'='estorno' THEN SELECT value INTO original FROM jsonb_array_elements(NEW.data->'movements') WHERE value->>'id'=movement->>'reverses' AND value->>'type'='baixa'; IF original IS NULL OR (original->>'value')::numeric<>amount OR (SELECT count(*) FROM jsonb_array_elements(NEW.data->'movements') WHERE value->>'reverses'=movement->>'reverses')<>1 THEN RAISE EXCEPTION 'Estorno inválido'; END IF; total:=total-amount; ELSE RAISE EXCEPTION 'Tipo de movimentação inválido'; END IF; IF total<0 OR total>(NEW.data->>'valor')::numeric THEN RAISE EXCEPTION 'Baixa excede saldo do título'; END IF; END LOOP; IF (NEW.data->>'status'='paga')<>(total=(NEW.data->>'valor')::numeric) THEN RAISE EXCEPTION 'Situação deve refletir saldo restante'; END IF; RETURN NEW; END $$;
CREATE TRIGGER tms_ledger_validate BEFORE INSERT OR UPDATE ON public.app_records FOR EACH ROW EXECUTE FUNCTION public.tms_ledger_validate();
CREATE OR REPLACE FUNCTION public.tms_document_immutable() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NEW.collection='cteDocuments' AND TG_OP='UPDATE' AND (NEW.data->>'chave' IS DISTINCT FROM OLD.data->>'chave' OR NEW.data->>'valorFiscal' IS DISTINCT FROM OLD.data->>'valorFiscal' OR NEW.data->>'xmlOriginal' IS DISTINCT FROM OLD.data->>'xmlOriginal') THEN RAISE EXCEPTION 'Documento fiscal original não pode ser alterado'; END IF; IF NEW.collection='orders' AND TG_OP='UPDATE' AND (NEW.data->>'chaveNFe' IS DISTINCT FROM OLD.data->>'chaveNFe') THEN RAISE EXCEPTION 'Chave fiscal original não pode ser alterada'; END IF; RETURN NEW; END $$;
CREATE TRIGGER tms_document_immutable BEFORE UPDATE ON public.app_records FOR EACH ROW EXECUTE FUNCTION public.tms_document_immutable();